CREATE TABLE departments (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE customers (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(160) NOT NULL, phone VARCHAR(30) NOT NULL, identity_reference VARCHAR(80) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NULL UNIQUE, department_id BIGINT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('member','superadmin','reception','accounting','management','housekeeping') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (customer_id) REFERENCES customers(id), FOREIGN KEY (department_id) REFERENCES departments(id));
CREATE TABLE room_types (id BIGINT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, capacity INT NOT NULL, nightly_price INT NOT NULL, breakfast_price INT NOT NULL, description TEXT, image_url VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE rooms (id BIGINT PRIMARY KEY AUTO_INCREMENT, type_id BIGINT NOT NULL, code VARCHAR(16) NOT NULL UNIQUE, status ENUM('ready','occupied','dirty','repair') NOT NULL DEFAULT 'ready', area_sqm INT NULL, FOREIGN KEY (type_id) REFERENCES room_types(id), INDEX (type_id, status));
CREATE TABLE repair_closures (id BIGINT PRIMARY KEY AUTO_INCREMENT, room_id BIGINT NOT NULL, from_date DATE NOT NULL, to_date DATE NOT NULL, reason TEXT NOT NULL, closed_by BIGINT NOT NULL, opened_by BIGINT NULL, opened_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (room_id) REFERENCES rooms(id), FOREIGN KEY (closed_by) REFERENCES accounts(id), FOREIGN KEY (opened_by) REFERENCES accounts(id));
CREATE TABLE promotions (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, percent_off DECIMAL(5,2) NOT NULL, priority INT NOT NULL DEFAULT 100, start_date DATE NOT NULL, end_date DATE NOT NULL, min_nights INT NOT NULL DEFAULT 1, min_rooms INT NOT NULL DEFAULT 1, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NOT NULL, account_id BIGINT NULL, source ENUM('online','walk_in') NOT NULL, check_in DATE NOT NULL, check_out DATE NOT NULL, guests INT NOT NULL, status ENUM('held','pending_review','confirmed','checked_in','checked_out','cancelled','no_show','replacement_pending') NOT NULL DEFAULT 'held', hold_until DATETIME NULL, total INT NOT NULL, room_subtotal INT NOT NULL, service_subtotal INT NOT NULL, deposit_due INT NOT NULL, price_snapshot JSON NOT NULL, late_arrival_at DATETIME NULL, late_arrival_contact TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (customer_id) REFERENCES customers(id), FOREIGN KEY (account_id) REFERENCES accounts(id), INDEX (check_in, check_out, status), INDEX (account_id, created_at));
CREATE TABLE booking_rooms (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, type_id BIGINT NOT NULL, guests INT NOT NULL, room_id BIGINT NULL, nightly_price INT NOT NULL, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (type_id) REFERENCES room_types(id), FOREIGN KEY (room_id) REFERENCES rooms(id), INDEX (room_id));
CREATE TABLE room_assignments (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_room_id BIGINT NOT NULL, old_room_id BIGINT NULL, new_room_id BIGINT NOT NULL, assigned_by BIGINT NOT NULL, approved_by BIGINT NULL, reason TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_room_id) REFERENCES booking_rooms(id), FOREIGN KEY (old_room_id) REFERENCES rooms(id), FOREIGN KEY (new_room_id) REFERENCES rooms(id), FOREIGN KEY (assigned_by) REFERENCES accounts(id), FOREIGN KEY (approved_by) REFERENCES accounts(id));
CREATE TABLE booking_status_history (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, old_status VARCHAR(40) NULL, new_status VARCHAR(40) NOT NULL, actor_id BIGINT NULL, reason TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (actor_id) REFERENCES accounts(id));
CREATE TABLE booking_services (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, kind ENUM('breakfast','fitness','sauna','tour') NOT NULL, service_date DATE NULL, quantity INT NOT NULL, unit_price INT NOT NULL, total INT NOT NULL, status ENUM('active','cancelled') NOT NULL DEFAULT 'active', created_by BIGINT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (created_by) REFERENCES accounts(id));
CREATE TABLE tour_slots (id BIGINT PRIMARY KEY AUTO_INCREMENT, tour_date DATE NOT NULL, time_label TIME NOT NULL, capacity INT NOT NULL DEFAULT 10, UNIQUE (tour_date, time_label));
CREATE TABLE tour_participants (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, slot_id BIGINT NOT NULL, participant_label VARCHAR(160) NOT NULL, price INT NOT NULL, status ENUM('held','confirmed','cancelled') NOT NULL DEFAULT 'held', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (slot_id) REFERENCES tour_slots(id), INDEX (slot_id, status));
CREATE TABLE payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, amount INT NOT NULL, method ENUM('transfer_demo','online_demo','reception_demo') NOT NULL, evidence_path VARCHAR(500) NULL, status ENUM('pending_review','approved','rejected') NOT NULL DEFAULT 'pending_review', auto_check VARCHAR(80) NOT NULL, submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewed_at DATETIME NULL, reviewed_by BIGINT NULL, rejection_reason TEXT NULL, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (reviewed_by) REFERENCES accounts(id), INDEX (status, submitted_at));
CREATE TABLE payment_escalations (id BIGINT PRIMARY KEY AUTO_INCREMENT, payment_id BIGINT NOT NULL, requested_by BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (payment_id) REFERENCES payments(id), FOREIGN KEY (requested_by) REFERENCES accounts(id));
CREATE TABLE refunds (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, amount INT NOT NULL, reason VARCHAR(80) NOT NULL, status ENUM('requested','approved','rejected','recorded') NOT NULL DEFAULT 'requested', requested_by BIGINT NOT NULL, decided_by BIGINT NULL, recorded_by BIGINT NULL, decided_at DATETIME NULL, recorded_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (requested_by) REFERENCES accounts(id), FOREIGN KEY (decided_by) REFERENCES accounts(id), FOREIGN KEY (recorded_by) REFERENCES accounts(id));
CREATE TABLE cleaning_tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, room_id BIGINT NOT NULL, booking_id BIGINT NOT NULL, status ENUM('pending','working','done') NOT NULL DEFAULT 'pending', employee_id BIGINT NULL, started_at DATETIME NULL, finished_at DATETIME NULL, FOREIGN KEY (room_id) REFERENCES rooms(id), FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (employee_id) REFERENCES accounts(id));
CREATE TABLE damage_reports (id BIGINT PRIMARY KEY AUTO_INCREMENT, room_id BIGINT NOT NULL, booking_id BIGINT NULL, reporter_id BIGINT NOT NULL, details TEXT NOT NULL, image_path VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (room_id) REFERENCES rooms(id), FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (reporter_id) REFERENCES accounts(id));
CREATE TABLE replacement_proposals (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_room_id BIGINT NOT NULL, proposed_room_id BIGINT NOT NULL, status ENUM('pending','accepted','declined') NOT NULL DEFAULT 'pending', proposed_by BIGINT NOT NULL, decided_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_room_id) REFERENCES booking_rooms(id), FOREIGN KEY (proposed_room_id) REFERENCES rooms(id), FOREIGN KEY (proposed_by) REFERENCES accounts(id));
CREATE TABLE reviews (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, account_id BIGINT NOT NULL, rating INT NOT NULL, content TEXT NOT NULL, visible BOOLEAN NOT NULL DEFAULT TRUE, hidden_reason TEXT NULL, hidden_by BIGINT NULL, hidden_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (account_id) REFERENCES accounts(id), FOREIGN KEY (hidden_by) REFERENCES accounts(id));
CREATE TABLE attractions (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, description TEXT NOT NULL, season VARCHAR(40) NOT NULL, image_url VARCHAR(500) NULL, visible BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE chat_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_id BIGINT NOT NULL, sender_id BIGINT NOT NULL, recipient_id BIGINT NULL, content TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (account_id) REFERENCES accounts(id), FOREIGN KEY (sender_id) REFERENCES accounts(id), FOREIGN KEY (recipient_id) REFERENCES accounts(id));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_id BIGINT NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id VARCHAR(80) NOT NULL, before_json JSON NULL, after_json JSON NULL, reason TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (actor_id) REFERENCES accounts(id), INDEX (entity, entity_id), INDEX (created_at));
